    kept_length = len(kept_rows)
    if kept_length > 0:
        rotation_amount = final_state % kept_length
        kept_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    eligible_days = []
    for row in kept_rows:
        if isinstance(row, list) and len(row) == 2:
            day, is_blackout = row
            if isinstance(day, int) and isinstance(is_blackout, bool):
                if not is_blackout and day % 5 != 0:
                    eligible_days.append(day)

    distinct_days = sorted(list(set(eligible_days))) #remove duplicates and sort
